# tests/test_recommender.py
from pathlib import Path

import pytest

from src.recommender import CareerRecommender

DATA = Path(__file__).resolve().parents[1] / "data" / "careers.csv"


@pytest.fixture(scope="module")
def rec():
    return CareerRecommender(DATA)   # loads the model once for the module


def test_data_profile_ranks_a_data_role_first(rec):
    matches = rec.recommend("I know Python, SQL, machine learning, and data visualization.", top_k=3)
    assert "Data" in matches[0].career_title or "Analyst" in matches[0].career_title


def test_results_are_sorted_by_similarity(rec):
    matches = rec.recommend("I build React frontends with JavaScript, HTML and CSS.", top_k=5)
    sims = [m.similarity for m in matches]
    assert sims == sorted(sims, reverse=True)


def test_gap_excludes_skills_already_present(rec):
    matches = rec.recommend("Python, SQL, Docker, Kubernetes, Terraform", top_k=3)
    for m in matches:
        assert not set(s.lower() for s in m.matched_skills) & set(s.lower() for s in m.missing_skills)

def mean_reciprocal_rank(ranked_titles: list[list[str]], expected: list[str]) -> float:
    total = 0.0
    for titles, want in zip(ranked_titles, expected):
        for i, t in enumerate(titles, start=1):
            if t == want:
                total += 1 / i
                break
    return total / len(expected)
